"""Builds taxonomy.json and checks it: shape, guide anchors, guide coverage,
guide lines per page, the tool groups and every raw record's best home."""
import collections
import glob
import json
import math
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from heads import all_heads  # noqa: E402
from pages_a import SECTIONS_A  # noqa: E402
from pages_b import SECTIONS_B  # noqa: E402
from pages_c import SECTIONS_C  # noqa: E402

OUT = os.path.join(HERE, '..', 'taxonomy.json')
RAW = os.path.join(HERE, '..', 'raw')
FILES = {
    'rd': 'README', 'as': 'assistant', 'au': 'audio', 'cl': 'canvas-and-layers', 'cp': 'captions',
    'ct': 'cleanup-tools', 'cg': 'color-grading', 'ed': 'editing', 'ex': 'export', 'gr': 'graphics',
    'hc': 'hdr-and-color', 'mc': 'mcp', 'ms': 'menus-and-shortcuts', 'mt': 'motion-and-transitions',
    'mu': 'multicam', 'pm': 'projects-and-media', 'sr': 'screen-recording', 'st': 'settings',
    'sp': 'speed', 'tl': 'timeline', 'tr': 'transcript', 'vf': 'vertical-and-framing',
}


def expand(ref):
    key, anchor = ref.split('#', 1)
    if key == 'api':
        return f'docs/graphics-api.md#{anchor}'
    return f'docs/guide/{FILES[key]}.md#{anchor}'


def build():
    sections = []
    for order, s in enumerate(SECTIONS_A + SECTIONS_B + SECTIONS_C, 1):
        pages = []
        for porder, (pid, title, kind, scope, guide) in enumerate(s['pages'], 1):
            pages.append(dict(slug=f"{s['id']}/{pid}", title=title, order=porder, kind=kind,
                              scope=scope, guide=[expand(g) for g in guide]))
        sections.append(dict(id=s['id'], title=s['title'], order=order, summary=s['summary'],
                             areas=s['areas'], pages=pages))
    return dict(sections=sections)


def check(tax):
    problems = []
    heads = all_heads()
    index = {(f, h['anchor']): h for f, hs in heads.items() for h in hs}
    slugs = collections.Counter()
    kinds = {'feature', 'concept', 'howto', 'reference', 'overview'}
    for s in tax['sections']:
        for p in s['pages']:
            slugs[p['slug']] += 1
            if not re.fullmatch(r'[a-z0-9]+(-[a-z0-9]+)*/[a-z0-9]+(-[a-z0-9]+)*', p['slug']):
                problems.append(f"bad slug {p['slug']}")
            if not p['slug'].startswith(s['id'] + '/'):
                problems.append(f"slug outside section {p['slug']}")
            if p['kind'] not in kinds:
                problems.append(f"kind {p['slug']}")
            if re.search(r'colou?r', p['slug'].replace('color', '')) or 'colour' in p['slug']:
                problems.append(f"british slug {p['slug']}")
            sentences = len(re.findall(r'[.!?](\s|$)', re.sub(r'\.(cube|framejob|fjgraphic|fjcursor|webm|mkv|md|ts)\b|Rec\. 709|docs/graphics-api\.md', 'X', p['scope'])))
            if sentences > 2:
                problems.append(f"scope {sentences} sentences: {p['slug']}")
            for g in p['guide']:
                f, a = g.split('#', 1)
                if (f, a) not in index:
                    problems.append(f"no anchor {g} on {p['slug']}")
    for k, n in slugs.items():
        if n > 1:
            problems.append(f'duplicate slug {k}')
    # Cross-references written in scopes must name real pages.
    ids = set(slugs)
    sec_ids = {s['id'] for s in tax['sections']}
    for s in tax['sections']:
        for p in s['pages']:
            for m in re.findall(r'\b([a-z-]+/[a-z0-9-]+)\b', p['scope']):
                if m.split('/')[0] in sec_ids and m not in ids:
                    problems.append(f"scope link {m} on {p['slug']}")
    # Guide coverage: every heading is cited, or sits under a cited heading.
    cited = collections.defaultdict(set)
    for s in tax['sections']:
        for p in s['pages']:
            for g in p['guide']:
                f, a = g.split('#', 1)
                cited[(f, a)].add(p['slug'])
    uncovered = []
    for f, hs in heads.items():
        for k, h in enumerate(hs):
            if h['level'] == 1:
                continue
            ok = (f, h['anchor']) in cited
            if not ok:
                for g in hs:
                    if 1 < g['level'] < h['level'] and g['line'] < h['line'] < g['end'] and (f, g['anchor']) in cited:
                        ok = True
            if not ok:
                uncovered.append(f"{f}#{h['anchor']} [{h['end'] - h['line']}]")
    # Guide lines a page draws on, a cited heading counting only what no other page cites below it.
    long_pages = []
    for s in tax['sections']:
        for p in s['pages']:
            total = 0
            for g in p['guide']:
                f, a = g.split('#', 1)
                h = index[(f, a)]
                if h['level'] == 1:
                    total += h['own']
                    continue
                n = h['end'] - h['line']
                for c in heads[f]:
                    if h['line'] < c['line'] < h['end'] and (f, c['anchor']) in cited:
                        n -= c['end'] - c['line']
                total += max(n, 0)
            if total > 150:
                long_pages.append((total, p['slug']))
    return problems, uncovered, sorted(long_pages, reverse=True)


TOKEN = re.compile(r"[a-z0-9_+×−-]+")
STOP = set('a an and the of to in on at for with from by is it its as or be into that this your you can not no one each it\'s what how when which than'.split())


def toks(text):
    return [t for t in TOKEN.findall(text.lower()) if t not in STOP and len(t) > 1]


def stem(t):
    for suf in ('ing', 'ers', 'es', 's', 'ed'):
        if t.endswith(suf) and len(t) > len(suf) + 3:
            return t[:-len(suf)]
    return t


def homes(tax):
    recs = []
    for f in sorted(glob.glob(RAW + '/*.json')):
        recs += json.load(open(f))
    pages = [(s, p) for s in tax['sections'] for p in s['pages']]
    docs = []
    df = collections.Counter()
    for s, p in pages:
        title = {stem(t) for t in toks(p['title'] + ' ' + p['slug'].split('/')[1].replace('-', ' '))}
        body = {stem(t) for t in toks(p['scope'])}
        docs.append((title, body))
        for t in title | body:
            df[t] += 1
    n = len(pages)
    idf = lambda t: math.log(1 + n / (1 + df[t]))
    area_sec = {a: s['id'] for s in tax['sections'] for a in s['areas']}
    weak = []
    assign = collections.Counter()
    for r in recs:
        q = {stem(t) for t in toks(r['name'])}
        q2 = {stem(t) for t in toks(' '.join(r.get('ui') or []))}
        best = (0, None)
        for (s, p), (title, body) in zip(pages, docs):
            sc = 0
            for t in q:
                if t in title:
                    sc += 2 * idf(t)
                elif t in body:
                    sc += idf(t)
            for t in q2 - q:
                if t in title or t in body:
                    sc += 0.3 * idf(t)
            if area_sec.get(r['area']) == s['id']:
                sc *= 1.5
            if sc > best[0]:
                best = (sc, p['slug'])
        assign[best[1]] += 1
        full = sum(idf(t) * 2 for t in q) or 1
        ratio = best[0] / full
        if ratio < 0.35:
            weak.append((r['area'], r['name'], round(ratio, 2), best[1]))
    return recs, weak, assign


if __name__ == '__main__':
    tax = build()
    json.dump(tax, open(OUT, 'w'), indent=1, ensure_ascii=False)
    total = sum(len(s['pages']) for s in tax['sections'])
    print('pages', total)
    for s in tax['sections']:
        print(f"{s['order']:>2} {s['id']:<18} {len(s['pages'])}")
    problems, uncovered, long_pages = check(tax)
    print('\nPROBLEMS', len(problems))
    print('\n'.join(problems))
    print('\nUNCOVERED', len(uncovered))
    print('\n'.join(uncovered))
    print('\nLONG (guide lines > 150)', long_pages)
    catalog = open(os.path.join(HERE, 'catalog-tools.txt')).read().split()
    dev = 'snapshot_ui perform_menu_item cancel_sheet select_inspector_tab play_preview graphic_memory loudness_meter land_recording analysis_job transcript_view playback_rebuilds assistant_send assistant_answer'.split()
    tools = [t for t in catalog if t not in dev]
    groups = {p['slug']: p for s in tax['sections'] for p in s['pages'] if p['slug'].startswith('mcp/tools-')}
    seen = collections.Counter()
    for slug, p in groups.items():
        first = re.split(r'[:.]| with | and feeding| and every| and its', p['scope'])[0]
        for t in tools:
            if re.search(r'(?<![a-z_])' + re.escape(t) + r'(?![a-z_])', first):
                seen[t] += 1
    print('\nTOOLS', len(tools), 'missing', [t for t in tools if seen[t] == 0], 'doubled', [t for t in tools if seen[t] > 1])
    if '--homes' in sys.argv:
        recs, weak, assign = homes(tax)
